patterns.uml:
classDiagram
class Vehiculo {
  <<interface>>
  +entregar() void
}
class Auto
class Moto
Vehiculo <|.. Auto
Vehiculo <|.. Moto
class Creador {
  <<abstract>>
  +crearVehiculo() Vehiculo
  +vender() void
}
class FabricaAuto {
  +crearVehiculo() Vehiculo
}
class FabricaMoto {
  +crearVehiculo() Vehiculo
}
Creador <|-- FabricaAuto
Creador <|-- FabricaMoto
Creador ..> Vehiculo : utiliza
FabricaAuto ..> Auto : crea
FabricaMoto ..> Moto : crea

classDiagram
class Elemento {
  <<abstract>>
  +tamano() float
}
class Archivo {
  -float bytes
  +tamano() float
}
class Carpeta {
  -Elemento[] hijos
  +agregar(Elemento e) void
  +quitar(Elemento e) void
  +tamano() float
}
Elemento <|-- Archivo
Elemento <|-- Carpeta
Carpeta "0..1" o-- "0..*" Elemento : hijos
class Cliente
Cliente --> Elemento

